// Throwaway randomised-sweep case generator. Deterministic LCG, no Math.random.
import { writeFileSync } from 'node:fs';

let S = 20260807 >>> 0;
function next() { S = (S * 1103515245 + 12345) >>> 0; return S; }
function rnd() { return next() / 4294967296; }
function ri(n) { return next() % n; }            // 0..n-1
function pick(a) { return a[ri(a.length)]; }
function chance(p) { return rnd() < p; }

// ---------------------------------------------------------------- --a builders
function ascii1_7f(len) {                       // all of 0x01..0x7f
  let s = '';
  for (let i = 0; i < len; i++) s += String.fromCharCode(1 + ri(0x7f));
  return s;
}
function asciiPrintable(len) {
  let s = '';
  for (let i = 0; i < len; i++) s += String.fromCharCode(0x20 + ri(0x5f));
  return s;
}
function latin1(len) {                          // mix of ASCII + 0x80..0xff
  let s = '';
  for (let i = 0; i < len; i++) {
    s += chance(0.5) ? String.fromCharCode(1 + ri(0x7f)) : String.fromCharCode(0x80 + ri(0x80));
  }
  return s;
}
function bmp(len) {                             // 0x0100..0xffff, surrogates mostly avoided
  let s = '';
  for (let i = 0; i < len; i++) {
    let c;
    do { c = 0x100 + ri(0xff00); } while (c >= 0xd800 && c <= 0xdfff && !chance(0.02));
    s += String.fromCharCode(c);
  }
  return s;
}
function astral(len) {                           // U+10000..U+10FFFF
  let s = '';
  for (let i = 0; i < len; i++) s += String.fromCodePoint(0x10000 + ri(0x100000));
  return s;
}
function mixedPlanes(len) {
  let s = '';
  for (let i = 0; i < len; i++) {
    const k = ri(4);
    if (k === 0) s += String.fromCharCode(1 + ri(0x7f));
    else if (k === 1) s += String.fromCharCode(0x80 + ri(0x180));
    else if (k === 2) { let c; do { c = 0x100 + ri(0xff00); } while (c >= 0xd800 && c <= 0xdfff); s += String.fromCharCode(c); }
    else s += String.fromCodePoint(0x10000 + ri(0x100000));
  }
  return s;
}
// Length distribution: heavy on tiny, occasional huge up to 4000.
function randLen() {
  const k = ri(100);
  if (k < 8) return 0;
  if (k < 45) return 1 + ri(4);
  if (k < 75) return 1 + ri(40);
  if (k < 90) return 1 + ri(300);
  if (k < 97) return 1 + ri(1500);
  return ri(4001);
}
function randA() {
  const k = ri(100);
  const n = randLen();
  if (k < 26) return ascii1_7f(n);
  if (k < 40) return asciiPrintable(n);
  if (k < 58) return latin1(n);
  if (k < 74) return bmp(n);
  if (k < 88) return astral(n);
  return mixedPlanes(n);
}

// ---------------------------------------------------------------- --b builders
const ND = [ // non-ASCII Unicode decimal digits (category Nd), zero code points
  0x0660, 0x06f0, 0x07c0, 0x0966, 0x09e6, 0x0a66, 0x0ae6, 0x0b66, 0x0be6,
  0x0c66, 0x0ce6, 0x0d66, 0x0e50, 0x0ed0, 0x0f20, 0x1040, 0x17e0, 0x1810,
  0x1946, 0x19d0, 0x1a80, 0x1b50, 0x1c40, 0xa620, 0xa8d0, 0xff10,
];
const ND_ASTRAL = [0x104a0, 0x110f0, 0x11066, 0x1d7ce, 0x1d7d8, 0x1e950];
const NOT_ND_DIGITY = ['²', '½', 'Ⅰ', '〇', '፩', '⁰', '⓪', '¹', '\u2festival'.slice(0, 1)];
const INT_WS = ['\t', '\n', '\v', '\f', '\r', '', '', '', '', ' ',
  '', ' ', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', '　'];
const NBSP_LIKE = ['​', '⁠', '﻿', '᠎'];  // NOT int-whitespace

function digits(n) { let s = ''; for (let i = 0; i < n; i++) s += String(ri(10)); return s; }
function randMagnitude() {
  const k = ri(100);
  let n;
  if (k < 20) return String(ri(20));
  if (k < 35) n = 1 + ri(3);
  else if (k < 55) n = 1 + ri(10);
  else if (k < 70) n = 1 + ri(20);
  else if (k < 82) n = 15 + ri(40);
  else if (k < 92) n = 60 + ri(150);
  else n = 150 + ri(400);            // hundreds of digits
  let s = digits(n);
  if (chance(0.35)) s = '0'.repeat(ri(4)) + s;   // leading zeros
  if (chance(0.4)) s = (chance(0.6) ? '-' : '+') + s;
  return s;
}
