  const k = ri(24);
  switch (k) {
    case 0: return '';
    case 1: return pick(['-', '+', '--', '+-', '-+']);
    case 2: return digits(1 + ri(4)) + pick(['.0', '.', 'e5', 'E5', 'l', 'L', 'j']);
    case 3: return pick(['0x', '0x1f', '0b101', '0o17', '0X10', '0B1']);
    case 4: return digits(1 + ri(3)) + '_' + digits(1 + ri(3));      // underscore: valid
    case 5: return '_' + digits(1 + ri(3));                           // invalid
    case 6: return digits(1 + ri(3)) + '__' + digits(1 + ri(3));      // invalid
    case 7: return digits(1 + ri(3)) + '_';                           // invalid
    case 8: return pick(INT_WS).repeat(1 + ri(3)) + digits(1 + ri(5));
    case 9: return digits(1 + ri(5)) + pick(INT_WS).repeat(1 + ri(3));
    case 10: { const w = pick(INT_WS); return w + w + pick(['-', '+', '']) + digits(1 + ri(4)) + w; }
    case 11: return pick(INT_WS) + pick(['-', '+']) + pick(INT_WS) + digits(1 + ri(3)); // ws after sign: invalid
    case 12: return pick(NBSP_LIKE) + digits(1 + ri(3));
    case 13: return digits(1 + ri(3)) + pick(NBSP_LIKE);
    case 14: return pick(NOT_ND_DIGITY).repeat(1 + ri(2));
    case 15: return digits(1 + ri(3)) + pick(NOT_ND_DIGITY);
    case 16: return pick(['nan', 'inf', 'Inf', '-inf', 'NaN', 'None', 'True', 'false']);
    case 17: return ascii1_7f(1 + ri(6));
    case 18: return latin1(1 + ri(5));
    case 19: return bmp(1 + ri(4));
    case 20: return astral(1 + ri(3));
    case 21: return digits(1 + ri(3)) + ' ' + digits(1 + ri(3));
    case 22: return pick(['1,000', '1 000', '١٢٣abc', '12٠', '٠3']);
    default: return digits(1 + ri(3)) + pick(['٠', '１', 'ᵼe']);
  }
}
function randB() {
  const k = ri(100);
  if (k < 46) return randMagnitude();
  if (k < 60) return ndString();
  return malformedInt();
}

// ------------------------------------------------- token shuffling / omission
function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) { const j = ri(i + 1); [arr[i], arr[j]] = [arr[j], arr[i]]; }
  return arr;
}
function junkToken() {
  return pick(['--', '-', '--c', '-c', '-ab', '--a=', '--b=', '--A', '--B', 'pos',
    '---', '--a--', '=', '--=1', '-5', '-x', '--b=--a', '@file', '--é']);
}
function weirdCase() {
  const a = randA(), b = randB();
  const style = ri(12);
  let toks;
  switch (style) {
    case 0: toks = ['--b', b, '--a', a]; break;                       // swapped order
    case 1: toks = ['--a=' + a, '--b=' + b]; break;                   // = form
    case 2: toks = ['--a', a, '--b', b, '--a', randA()]; break;       // duplicated --a
    case 3: toks = ['--b', b, '--b', randB(), '--a', a]; break;       // duplicated --b
    case 4: toks = ['--a', a]; break;                                 // --b omitted
    case 5: toks = ['--b', b]; break;                                 // --a omitted
    case 6: toks = []; break;                                         // both omitted
    case 7: toks = ['--a', a, '--b']; break;                          // dangling --b
    case 8: toks = ['--a', '--b', b]; break;                          // --a swallows? / missing
    case 9: toks = shuffle(['--a', a, '--b', b]); break;              // fully shuffled
    case 10: toks = ['--a', a, '--b', b, junkToken()]; break;         // trailing junk
    default: {                                                        // junk sprinkled + shuffled
      toks = ['--a', a, '--b', b];
      const n = 1 + ri(3);
      for (let i = 0; i < n; i++) toks.splice(ri(toks.length + 1), 0, junkToken());
      if (chance(0.5)) shuffle(toks);
    }
  }
  return toks;
}

// ------------------------------------------------------------------ emit cases
const BATCHES = 24, PER = 112;
let idx = 0;
const names = [];
for (let bnum = 0; bnum < BATCHES; bnum++) {
  const cases = [];
  for (let i = 0; i < PER; i++) {
    idx++;
    let argv;
    if (ri(100) < 22) argv = weirdCase();
    else argv = chance(0.5) ? ['--a', randA(), '--b', randB()] : ['--b', randB(), '--a', randA()];
    cases.push({ name: `sweep-${idx}`, argv });
  }
  const f = `/tmp/sweep-${String(bnum).padStart(2, '0')}.json`;
  writeFileSync(f, JSON.stringify(cases));
  names.push(f);
}
console.log(`wrote ${BATCHES} batches x ${PER} = ${idx} cases`);
console.log(names.join('\n'));

