    case 12: return pick(NBSP_LIKE) + digits(1 + ri(3));
    case 13: return digits(1 + ri(3)) + pick(NBSP_LIKE);
    case 14: { let s = ''; const n = 1 + ri(2); for (let i = 0; i < n; i++) s += pick(NOT_ND); return s; }
    case 15: return digits(1 + ri(3)) + pick(NOT_ND);
    case 16: return pick(['nan', 'inf', 'Inf', '-inf', 'NaN', 'None', 'True', 'false', 'null']);
    case 17: return ascii1_7f(1 + ri(6));
    case 18: return latin1(1 + ri(5));
    case 19: return bmp(1 + ri(4));
    case 20: return astral(1 + ri(3));
    case 21: return digits(1 + ri(3)) + ' ' + digits(1 + ri(3));
    case 22: return pick(['1,000', '1 000', '١٢٣abc', '12٠', '٠3',
      '۱١', '１２', 'ᵼeᵼf']);
    default: return digits(1 + ri(3)) + pick([cp(0x660), cp(0xff11), cp(0x1d7ce), 'e', 'E']);
  }
}
function randB() {
  const k = ri(100);
  if (k < 46) return randMagnitude();
  if (k < 60) return ndString();
  return malformedInt();
}

// ------------------------------------------------- token shuffling / omission
function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) { const j = ri(i + 1); [arr[i], arr[j]] = [arr[j], arr[i]]; }
  return arr;
}
function junkToken() {
  return pick(['--', '-', '--c', '-c', '-ab', '--a=', '--b=', '--A', '--B', 'pos',
    '---', '--a--', '=', '--=1', '-5', '-x', '--b=--a', '@file', '--é',
    '--á', '––a', '--b=', '-b', '-a']);
}
function weirdCase() {
  const a = randA(), b = randB();
  let toks;
  switch (ri(12)) {
    case 0: toks = ['--b', b, '--a', a]; break;                       // swapped order
    case 1: toks = ['--a=' + a, '--b=' + b]; break;                   // = form
    case 2: toks = ['--a', a, '--b', b, '--a', randA()]; break;       // duplicated --a
    case 3: toks = ['--b', b, '--b', randB(), '--a', a]; break;       // duplicated --b
    case 4: toks = ['--a', a]; break;                                 // --b omitted
    case 5: toks = ['--b', b]; break;                                 // --a omitted
    case 6: toks = []; break;                                         // both omitted
    case 7: toks = ['--a', a, '--b']; break;                          // dangling --b
    case 8: toks = ['--a', '--b', b]; break;                          // --a eats an option?
    case 9: toks = shuffle(['--a', a, '--b', b]); break;              // fully shuffled
    case 10: toks = ['--a', a, '--b', b, junkToken()]; break;         // trailing junk
    default: {                                                        // junk sprinkled
      toks = ['--a', a, '--b', b];
      const n = 1 + ri(3);
      for (let i = 0; i < n; i++) toks.splice(ri(toks.length + 1), 0, junkToken());
      if (chance(0.5)) shuffle(toks);
    }
  }
  return toks;
}

// ------------------------------------------------------------------ emit cases
const BATCHES = Number(process.argv[2] ?? 24);
const PER = Number(process.argv[3] ?? 112);
const TAG = process.argv[4] ?? 'sweep';
if (process.argv[5]) S = Number(process.argv[5]) >>> 0;
let idx = 0;
for (let bnum = 0; bnum < BATCHES; bnum++) {
  const cases = [];
  for (let i = 0; i < PER; i++) {
    idx++;
    let argv;
    if (ri(100) < 22) argv = weirdCase();
    else argv = chance(0.5) ? ['--a', randA(), '--b', randB()] : ['--b', randB(), '--a', randA()];
    cases.push({ name: `${TAG}-${idx}`, argv });
  }
  writeFileSync(`/tmp/${TAG}-${String(bnum).padStart(2, '0')}.json`,
    JSON.stringify(cases));
}
console.log(`wrote ${BATCHES} batches x ${PER} = ${idx} cases, tag=${TAG}`);
